def success_projection(body):
    need(type(body) is bytes and 0<len(body)<=4096,'Rollover body bound')
    def pairs(items):
        out={}
        for k,v in items:need(k not in out,'Rollover duplicate');out[k]=v
        return out
    def constant(_):raise AssertionError('Rollover nonfinite')
    v=json.loads(body.decode('utf-8'),object_pairs_hook=pairs,parse_constant=constant)
    def fields(o,keys):need(type(o) is dict and set(o)==set(keys),'Rollover exact fields')
    def ints(o,keys,maxvalue):
        fields(o,keys)
        for k in keys:need(type(o[k]) is int and 0<=o[k]<=maxvalue,'Rollover count')
    fields(v,['version','provenance','constructorOriginal','prototypeObjectOriginal','staticOriginal','wrappedReflectionChanged','observerFault','state','tracks','recorders','uploads','unmounts','controls'])
    need(type(v['version']) is int and v['version']==4 and v['provenance']=='REAL_NATIVE_FIRST_START_FINAL_SEND' and v['state'] in ['UNCREATED','recording','paused','inactive'],'Second control labels')
    for k in ['constructorOriginal','prototypeObjectOriginal','staticOriginal','wrappedReflectionChanged','observerFault']:need(type(v[k]) is bool,'Rollover flags')
    ints(v['tracks'],['audio','live','ended'],8);need(v['tracks']['live']+v['tracks']['ended']==v['tracks']['audio'],'Rollover tracks');need(type(v['unmounts']) is int and v['unmounts']==0,'Single explicit fixture action')
    import re
    need(type(v['recorders']) is list and len(v['recorders'])<=1 and type(v['uploads']) is list and len(v['uploads'])==0,'Two native sources maximum')
    for i,r in enumerate(v['recorders']):
        fields(r,['ordinal','sameStream','state','startedAtMs','stoppedAtMs','stopRequestedAtMs','pausedAtMs','resumedAtMs','calls','events','chunks']);need(type(r['ordinal']) is int and r['ordinal']==i+1 and r['sameStream'] is True and r['state'] in ['recording','paused','inactive'],'Native ordinal/stream')
        need(type(r['startedAtMs']) is int and 0<=r['startedAtMs']<=600000,'Native start timestamp')
        for k in ['stoppedAtMs','stopRequestedAtMs','pausedAtMs','resumedAtMs']:need(r[k] is None or type(r[k]) is int and r['startedAtMs']<=r[k]<=600000,'Native method timestamp')
        need(i!=0 or r['pausedAtMs'] is None and r['resumedAtMs'] is None,'First recorder received second marks')
        need(r['resumedAtMs'] is None or r['pausedAtMs'] is not None and r['resumedAtMs']>=r['pausedAtMs'],'Second method order')
        ints(r['calls'],['start','pause','resume','stop'],2);ints(r['events'],['start','pause','resume','stop','data','error'],32)
        need(all(r['calls'][k]==r['events'][k]==0 for k in ['pause','resume','stop']),'First Start no later controls')
        c=r['chunks'];fields(c,['count','bytes','hash','drained']);need(type(c['count']) is int and 0<=c['count']<=16 and type(c['bytes']) is int and 0<=c['bytes']<=3500000 and type(c['drained']) is bool,'Native per-source chunks')
        need(c['hash'] is None or type(c['hash']) is str and re.fullmatch('[0-9a-f]{64}',c['hash']),'Native per-source digest');need(r['events']['stop']==1 and r['stoppedAtMs'] is not None and c['hash'] is not None if c['drained'] else c['hash'] is None,'Native per-source drain')
    for i,u in enumerate(v['uploads']):
        fields(u,['ordinal','segmentId','sequence','durationMs','bytes','mime','hash','mounted','atMs','returnedStatus']);need(type(u['ordinal']) is int and u['ordinal']==i+1 and type(u['sequence']) is int and u['sequence']==i and type(u['segmentId']) is str and re.fullmatch('[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}',u['segmentId']) and u['mounted'] is (i==0),'Different original segment/mount')
        need(u['returnedStatus'] is None or type(u['returnedStatus']) is int and u['returnedStatus']==503,'Actual local response marker')
        need(type(u['durationMs']) is int and (60000 if i==0 else 1)<=u['durationMs']<=150000 and type(u['bytes']) is int and 1<=u['bytes']<=3500000 and type(u['atMs']) is int and 0<=u['atMs']<=600000,'Native original File bounds')
        need(type(u['mime']) is str and re.fullmatch(r'audio/(webm|mp4)(;codecs=[a-z0-9,.-]{1,32})?',u['mime']) and type(u['hash']) is str and re.fullmatch('[0-9a-f]{64}',u['hash']),'Native File MIME/digest');need(i<len(v['recorders']),'Missing source recorder');r=v['recorders'][i];need(u['bytes']==r['chunks']['bytes'] and (r['chunks']['hash'] is None or u['hash']==r['chunks']['hash']),'Same native source File binding')
    if len(v['uploads'])==2:need(v['uploads'][0]['segmentId']!=v['uploads'][1]['segmentId'] and v['uploads'][0]['atMs']<=v['uploads'][1]['atMs'],'Actual different segment order')
fields(v['controls'],['status','count','cases']);need(type(v['controls']['count']) is int and type(v['controls']['cases']) is list and v['controls']=={'status':'INERT','count':0,'cases':[]},'First Start controls remain inert')
    return v
